select q.id, 'en', v.en_soru, v.en_secenekler
  from (values
  ('Manet''nin ''Flüt Çalan Çocuk'' tablosunda çocuğun kıyafeti hangi meslekle ilişkilidir?', 'The boy''s outfit in Manet''s ''The Fifer'' is associated with which occupation?', '["Soldier","Sailor","Shepherd","Cook"]'::jsonb),
